class _TTLCache(object):
    def __init__(self, maxsize, ttl, timer, typed):
        self._maxsize = maxsize
        self._ttl = ttl
        self._timer = timer
        self._typed = typed
        self._cache = {}
        self._metrics = _CacheInfo(0, 0, maxsize, 0)

    def __call__(self, func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            try:
                key = self._make_key(args, kwargs)
                with self._lock:
                    link = self._cache[key]
            except KeyError:
                value = func(*args, **kwargs)
                with self._lock:
                    if len(self._cache) >= self._maxsize:
                        self._remove_lru_item()
                    self._set_item(key, value)
                return value
            else:
                item, timestamp = link
                if self._has_expired(timestamp):
                    with self._lock:
                        del self._cache[key]
                    value = func(*args, **kwargs)
                    with self._lock:
                        self._set_item(key, value)
                else:
                    self._metrics = self._metrics._replace(hits=self._metrics.hits + 1)
                    return item

        @property
        def cache_info(self):
            with self._lock:
                return self._metrics

        def cleanup(self):
            with self._lock:
                now = self._timer()
                expired = [key for (key, (_, timestamp)) in self._cache.items() if self._has_expired(timestamp)]
                for key in expired:
                    del self._cache[key]
                    self._metrics = self._metrics._replace(currsize=self._metrics.currsize - 1)
                return expired

        def __len__(self):
            with self._lock:
                return self._metrics.currsize

        def __contains__(self, key):
            with self._lock:
                try:
                    key = self._make_key(key)
                    return self._cache[key] is not None
                except KeyError:
                    return False

