            if key in cache:
                use_count[key] += 1
                return cache[key]
            else:
                result = func(*args, **kwargs)
                if len(cache) >= maxsize:
                    for k, _ in itertools.chain(
                        sorted(use_count.items(), key=lambda item: item[1]),
                        itertools.islice(use_count.items(), maxsize)):
