def validate(self, inventory, extract_spec_version=False):
    if extract_spec_version:
        spec_version = inventory.get("type")
        if not spec_version or spec_version not in self.valid_spec_versions:
            spec_version = self.spec_version
    else:
        spec_version = self.spec_version

    # Check for required fields
    for field in self.required_fields:
        if field not in inventory:
            self.logger.error(f"Missing required field: {field} in inventory {inventory}")
            return False

    # Check field types
    for field, field_type in self.field_types.items():
        if field in inventory:
            if not isinstance(inventory[field], field_type):
                self.logger.error(f"Field {field} must be of type {field_type} in inventory {inventory}")
                return False

    # Check for valid values
    for field, valid_values in self.valid_values.items():
        if field in inventory:
            if inventory[field] not in valid_values:
                self.logger.error(f"Field {field} must be one of {valid_values} in inventory {inventory}")
                return False

    # Check for missing dependencies
    for field, dependencies in self.dependencies.items():
        if field in inventory and any(dependency not in inventory for dependency in dependencies):
            self.logger.error(f"Missing dependencies for field {field} in inventory {inventory}")
            return False

    # Check if the inventory is valid for the given spec version
    if spec_version not in self.valid_inventories:
        self.logger.error(f"Inventory is not valid for spec version {spec_version}")
        return False

    return True

