def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("Prior must be an InventoryValidator object")

    # Check that the prior inventory is a prior version of the current inventory
    if self.get_version() <= prior.get_version():
        raise ValueError("Prior inventory must be an earlier version than the current inventory")

    # Check that the prior inventory is consistent with the current inventory
    if not self.is_consistent_with(prior):
        raise ValueError("Prior inventory is not consistent with the current inventory")

    # Check that the prior inventory has all the required information
    if not prior.has_required_information():
        raise ValueError("Prior inventory does not have all the required information")

    # Check that the prior inventory has no conflicting information
    if prior.has_conflicting_information():
        raise ValueError("Prior inventory has conflicting information")

    # Check that the prior inventory meets the inventory validation criteria
    if not prior.meets_validation_criteria():
        raise ValueError("Prior inventory does not meet the inventory validation criteria")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for file in version.files:
        if file.logical_path in logical_path_map:
            logical_path_map[file.logical_path].add(file)
        else:
            logical_path_map[file.logical_path] = {file}
    return logical_path_map

