    if cli_args or answer_file_args:
        # If there are deprecated arguments, print a warning
        print("Warning: There are deprecated arguments. Please update your scripts to use the latest arguments.")

        # Check if there are any deprecated arguments in the cli_args
        for arg in cli_args:
            if arg in DEPRECATED_ARGS:
                print(f"  - Deprecated argument: {arg}")

        # Check if there are any deprecated arguments in the answer file
        for arg in answer_file_args:
            if arg in DEPRECATED_ARGS:
                print(f"  - Deprecated argument in answer file: {arg}")

        # Print a message to suggest updating the scripts
        print("Please update your scripts to use the latest arguments. The deprecated arguments will be removed in a future version.")

def get_silent_args(self, args):
    """list of silenced argument names

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_args = []
    for arg in args:
        if arg.startswith('_'):
            silent_args.append(arg)
    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided.

    Raises:
        ValueError: If a required argument is missing.
    """
    for arg in self.REQUIRED_ARGS:
        if arg not in args:
            raise ValueError(f"Required argument '{arg}' is missing.")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > self.length:
            raise ValueError("The value of argument '%s' is longer than the maximum length of %d." % (arg, self.length))

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if args[arg] < MIN or args[arg] > MAX:
            raise ValueError(f"Invalid argument value. Expected a value between {MIN} and {MAX} but got {args[arg]}")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if isinstance(arg, ControlArg):
            control_args[arg.name] = arg.value
        elif isinstance(arg, NestedArg):
            nested_args[arg.name] = arg.value
        elif isinstance(arg, CustomArg):
            custom_args[arg.name] = arg.value
        else:
            raise ValueError(f"Invalid argument type: {arg}")

    # Remove duplicate args
    for arg in control_args.keys():
        if arg in nested_args or arg in custom_args:
            raise ValueError(f"Duplicate argument: {arg}")

    return control_args, nested_args, custom_args

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace.
    :param ir_plugin: An InfraredPlugin object of the current plugin.
    :param playbook_path: The playbook to invoke.
    :param verbose: Ansible verbosity level.
    :param extra_vars: A dict of 'extra-vars' to pass to Ansible.
    :param ansible_args: A dict of 'ansible-playbook' arguments to pass to Ansible.
    """

    ansible_path = ir_workspace.injector.get('ansible_path')
    if ansible_path:
        args = [ansible_path, 'ansible-playbook', playbook_path]
    else:
        args = ['ansible-playbook', playbook_path]

    if verbose is not None:
        args.extend(['-v', str(verbose)])

    if extra_vars:
        args.extend(['-e', str(extra_vars)])

    if ansible_args:
        args.extend(str(arg) for arg in ansible_args)

    p = subprocess.Popen(args, cwd=ir_workspace.root_path, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    out, err = p.communicate()
    if p.returncode != 0:
        raise subprocess.CalledProcessError(p.returncode, " ".join(args))

    return out.decode('utf-8').strip(), err.decode('utf-8').strip()

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        plugin_spec = None
        plugin_spec = _load_plugin_spec(plugin_dir)
        _validate_plugin_spec(plugin_spec)
        return _flatten_dict(plugin_spec)
    except Exception as e:
        raise ValueError("Error getting plugin spec flatten dict: " + str(e))

def _load_plugin_spec(plugin_dir):
    spec_path = os.path.join(plugin_dir, "plugin_spec.json")
    if not os.path.exists(spec_path):
        return {}
    with open(spec_path, "r") as f:
        plugin_spec = json.load(f)
    return plugin_spec

def _validate_plugin_spec(plugin_spec):
    required_keys = ["name", "version", "entrypoint"]
    for key in required_keys:
        if key not in plugin_spec:
            raise ValueError("Invalid plugin spec, missing key: " + key)
    if not isinstance(plugin_spec["version"], str) or len(plugin_spec["version"]) == 0:
        raise ValueError("Invalid plugin spec, version must be a non-empty string")
    if not isinstance(plugin_spec["entrypoint"], str) or len(plugin_spec["entrypoint"]) == 0:
        raise ValueError("Invalid plugin spec, entrypoint must be a non-empty string")
    if "dependencies" in plugin_spec and not isinstance(plugin_spec["dependencies"], list):
        raise ValueError("Invalid plugin spec, dependencies must be a list")

def _flatten_dict(obj):
    flat_dict = {}
    for key, value in obj.items():
        flat_dict[key] = value
        if isinstance(value, dict):
            flat_dict.update(_flatten_dict(value))
    return flat_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if not os.environ.get("CONFIG_PATH"):
        os.environ["CONFIG_PATH"] = self.config_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"Path {path} does not start with root {root}")
    return path[len(root):]
